package com.supermarkettracker.infrastructure.persistence.entity;
import com.supermarkettracker.domain.model.enums.*; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.math.BigDecimal; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="pagamento") public class PagamentoEntity { @Id public UUID id; @Column(name="venda_id",nullable=false) public UUID vendaId; @Column(name="conta_bancaria_id") public UUID contaBancariaId; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="tipo_pagamento") public TipoPagamento tipo; @Column(nullable=false,precision=14,scale=2) public BigDecimal valor; @Enumerated(EnumType.STRING) @JdbcTypeCode(SqlTypes.NAMED_ENUM) @Column(nullable=false,columnDefinition="status_pagamento") public StatusPagamento status; @Column(name="recebido_em") public Instant recebidoEm; @Column(length=120) public String referencia; @Column(name="created_at",nullable=false) public Instant criadoEm; @Column(name="updated_at",nullable=false) public Instant atualizadoEm; public PagamentoEntity() {} }
